    public static let agentsWrite = Scope(rawValue: "agents:write")
    public static let agentsExecute = Scope(rawValue: "agents:execute")
    /// Action-level scopes for Apps
    public static let appsRead = Scope(rawValue: "apps:read")
    public static let appsWrite = Scope(rawValue: "apps:write")
    public static let appsExecute = Scope(rawValue: "apps:execute")
    /// Action-level scopes for Conversations/Chats
    public static let conversationsRead = Scope(rawValue: "conversations:read")
    public static let conversationsWrite = Scope(rawValue: "conversations:write")
    /// Action-level scopes for Files
    public static let filesRead = Scope(rawValue: "files:read")
    public static let filesWrite = Scope(rawValue: "files:write")
    /// Action-level scopes for Datastores
    public static let datastoresRead = Scope(rawValue: "datastores:read")
    public static let datastoresWrite = Scope(rawValue: "datastores:write")
    /// Action-level scopes for Flows
    public static let flowsRead = Scope(rawValue: "flows:read")
    public static let flowsWrite = Scope(rawValue: "flows:write")
    public static let flowsExecute = Scope(rawValue: "flows:execute")
    /// Action-level scopes for Projects
    public static let projectsRead = Scope(rawValue: "projects:read")
    public static let projectsWrite = Scope(rawValue: "projects:write")
    /// Action-level scopes for Teams
    public static let teamsRead = Scope(rawValue: "teams:read")
    public static let teamsWrite = Scope(rawValue: "teams:write")
