/// AppPricing configures all pricing using CEL expressions.
/// Empty expressions use defaults. All values in microcents.
public struct AppPricing: Codable {
    public var prices: [String: Int]?
    public var upstreamPricing: String?
    public var resourceExpression: String
    public var inferenceExpression: String
    public var royaltyExpression: String
    public var partnerExpression: String
    public var totalExpression: String
    /// Estimate is a single CEL expression for pre-execution cost estimation.
    /// Returns either an int (exact total in microcents) or a {"min": int, "max": int} map.
    /// Only has access to pre-execution variables: task_inputs, prices, fees, task_function.
    /// Used by the /estimate endpoint when the real expressions depend on post-execution data.
    /// Not needed when all fee expressions are already input-based (the system evaluates those directly).
    public var estimate: String?
    /// Estimable is computed at save time. True when all fee expressions can be
    /// evaluated from pre-execution data alone (task_inputs, prices, fees, task_function).
    public var estimable: Bool?
    public var description: String
    public var descriptionRendered: String?

    public init(
        prices: [String: Int]? = nil,
        upstreamPricing: String? = nil,
        resourceExpression: String = "",
        inferenceExpression: String = "",
        royaltyExpression: String = "",
        partnerExpression: String = "",
        totalExpression: String = "",
        estimate: String? = nil,
        estimable: Bool? = nil,
        description: String = "",
        descriptionRendered: String? = nil
    ) {
        self.prices = prices
