    public static let a2UIIcon = A2UIComponentType(rawValue: "Icon")
    public static let a2UIDivider = A2UIComponentType(rawValue: "Divider")
    public static let a2UIButton = A2UIComponentType(rawValue: "Button")
    public static let a2UITextField = A2UIComponentType(rawValue: "TextField")
    public static let a2UICheckBox = A2UIComponentType(rawValue: "CheckBox")
    public static let a2UISlider = A2UIComponentType(rawValue: "Slider")
    public static let a2UIDateTimeInput = A2UIComponentType(rawValue: "DateTimeInput")
    public static let a2UIChoicePicker = A2UIComponentType(rawValue: "ChoicePicker")
    public static let a2UICard = A2UIComponentType(rawValue: "Card")
    public static let a2UIModal = A2UIComponentType(rawValue: "Modal")
    public static let a2UITabs = A2UIComponentType(rawValue: "Tabs")
    /// Extensions (inferencesh/v1 catalog)
    public static let a2UIBadge = A2UIComponentType(rawValue: "Badge")
    public static let a2UISpacer = A2UIComponentType(rawValue: "Spacer")
    public static let a2UIChart = A2UIComponentType(rawValue: "Chart")
