/// A2UIComponent is the universal component representation.
/// Children are string IDs (flat adjacency list), not nested objects.
public struct A2UIComponent: Codable {
    public var id: String
    public var component: A2UIComponentType
    /// Layout
    public var children: [String]?
    public var justify: String?
    public var align: String?
    public var direction: String?
    public var gap: Int?
    /// Text
    public var text: JSONValue?
    public var variant: String?
    /// Image
    public var url: JSONValue?
    public var fit: String?
    /// Icon
    public var name: JSONValue?
    /// Divider
    public var axis: String?
    /// Button / Card
    public var child: String?
    public var primary: Bool?
    public var action: A2UIAction?
    /// TextField
    public var label: String?
    public var value: JSONValue?
    public var textFieldType: String?
    public var validationRegexp: String?
    public var placeholder: String?
    public var rows: Int?
    /// Slider
    public var minValue: Double?
    public var maxValue: Double?
    /// DateTimeInput
    public var enableDate: Bool?
    public var enableTime: Bool?
    /// ChoicePicker
    public var options: [A2UIChoiceOption]?
    public var selections: JSONValue?
    public var maxAllowedSelections: Int?
    /// Modal
    public var entryPointChild: String?
    public var contentChild: String?
    /// Tabs
    public var tabItems: [A2UITabItem]?
    /// Common
    public var accessibility: A2UIAccessibility?
    public var weight: Double?
    public var disabled: Bool?
    public var required: Bool?
    /// Extension: Badge
    public var badgeLabel: String?
    public var badgeVariant: String?
    /// Extension: Spacer
    public var minSize: JSONValue?
    /// Extension: Chart
    public var chartData: JSONValue?
    public var chartSeries: JSONValue?
    public var xAxis: JSONValue?
    public var showYAxis: Bool?
    public var showLegend: Bool?
    public var showTooltip: Bool?
    /// Extension: Form
    public var onSubmitAction: A2UIAction?
    /// Extension: Artifact
    public var artifactId: String?
    public var artifactVersionId: String?
    public var artifactTitle: String?
    public var artifactUrl: String?
    public var artifactFavicon: String?

    public init(
        id: String = "",
        component: A2UIComponentType,
        children: [String]? = nil,
        justify: String? = nil,
        align: String? = nil,
        direction: String? = nil,
        gap: Int? = nil,
        text: JSONValue? = nil,
        variant: String? = nil,
        url: JSONValue? = nil,
        fit: String? = nil,
        name: JSONValue? = nil,
        axis: String? = nil,
        child: String? = nil,
        primary: Bool? = nil,
        action: A2UIAction? = nil,
        label: String? = nil,
        value: JSONValue? = nil,
        textFieldType: String? = nil,
        validationRegexp: String? = nil,
        placeholder: String? = nil,
        rows: Int? = nil,
        minValue: Double? = nil,
        maxValue: Double? = nil,
        enableDate: Bool? = nil,
        enableTime: Bool? = nil,
        options: [A2UIChoiceOption]? = nil,
        selections: JSONValue? = nil,
        maxAllowedSelections: Int? = nil,
        entryPointChild: String? = nil,
        contentChild: String? = nil,
        tabItems: [A2UITabItem]? = nil,
        accessibility: A2UIAccessibility? = nil,
        weight: Double? = nil,
        disabled: Bool? = nil,
        required: Bool? = nil,
        badgeLabel: String? = nil,
        badgeVariant: String? = nil,
        minSize: JSONValue? = nil,
        chartData: JSONValue? = nil,
        chartSeries: JSONValue? = nil,
        xAxis: JSONValue? = nil,
        showYAxis: Bool? = nil,
        showLegend: Bool? = nil,
        showTooltip: Bool? = nil,
        onSubmitAction: A2UIAction? = nil,
        artifactId: String? = nil,
        artifactVersionId: String? = nil,
        artifactTitle: String? = nil,
        artifactUrl: String? = nil,
        artifactFavicon: String? = nil
    ) {
        self.id = id
        self.component = component
        self.children = children
        self.justify = justify
        self.align = align
        self.direction = direction
        self.gap = gap
        self.text = text
        self.variant = variant
        self.url = url
        self.fit = fit
        self.name = name
        self.axis = axis
        self.child = child
        self.primary = primary
        self.action = action
        self.label = label
        self.value = value
        self.textFieldType = textFieldType
        self.validationRegexp = validationRegexp
        self.placeholder = placeholder
        self.rows = rows
        self.minValue = minValue
        self.maxValue = maxValue
        self.enableDate = enableDate
        self.enableTime = enableTime
        self.options = options
        self.selections = selections
        self.maxAllowedSelections = maxAllowedSelections
        self.entryPointChild = entryPointChild
        self.contentChild = contentChild
        self.tabItems = tabItems
        self.accessibility = accessibility
        self.weight = weight
        self.disabled = disabled
        self.required = required
        self.badgeLabel = badgeLabel
        self.badgeVariant = badgeVariant
        self.minSize = minSize
        self.chartData = chartData
        self.chartSeries = chartSeries
        self.xAxis = xAxis
        self.showYAxis = showYAxis
        self.showLegend = showLegend
        self.showTooltip = showTooltip
        self.onSubmitAction = onSubmitAction
        self.artifactId = artifactId
        self.artifactVersionId = artifactVersionId
        self.artifactTitle = artifactTitle
        self.artifactUrl = artifactUrl
        self.artifactFavicon = artifactFavicon
    }

    enum CodingKeys: String, CodingKey {
        case id = "id"
        case component = "component"
        case children = "children"
        case justify = "justify"
        case align = "align"
        case direction = "direction"
        case gap = "gap"
        case text = "text"
        case variant = "variant"
        case url = "url"
        case fit = "fit"
        case name = "name"
        case axis = "axis"
        case child = "child"
        case primary = "primary"
        case action = "action"
        case label = "label"
        case value = "value"
        case textFieldType = "textFieldType"
        case validationRegexp = "validationRegexp"
        case placeholder = "placeholder"
        case rows = "rows"
        case minValue = "minValue"
        case maxValue = "maxValue"
        case enableDate = "enableDate"
        case enableTime = "enableTime"
        case options = "options"
        case selections = "selections"
        case maxAllowedSelections = "maxAllowedSelections"
        case entryPointChild = "entryPointChild"
        case contentChild = "contentChild"
        case tabItems = "tabItems"
        case accessibility = "accessibility"
        case weight = "weight"
        case disabled = "disabled"
        case required = "required"
        case badgeLabel = "badgeLabel"
        case badgeVariant = "badgeVariant"
        case minSize = "minSize"
        case chartData = "chartData"
        case chartSeries = "chartSeries"
        case xAxis = "xAxis"
        case showYAxis = "showYAxis"
        case showLegend = "showLegend"
        case showTooltip = "showTooltip"
        case onSubmitAction = "onSubmitAction"
        case artifactId = "artifactId"
        case artifactVersionId = "artifactVersionId"
        case artifactTitle = "artifactTitle"
        case artifactUrl = "artifactUrl"
        case artifactFavicon = "artifactFavicon"
    }
}

