/// Visibility represents the visibility level of a resource
public struct Visibility: RawRepresentable, Codable, Hashable, Sendable {
    public let rawValue: String
    public init(rawValue: String) { self.rawValue = rawValue }

    public static let `private` = Visibility(rawValue: "private")
    public static let team = Visibility(rawValue: "team")
    /// VisibilityOrg sits between team and public: visible to every member of
    /// every team in the owning team's org (INF-795 Phase 2).
    public static let org = Visibility(rawValue: "org")
    public static let `public` = Visibility(rawValue: "public")
    public static let unlisted = Visibility(rawValue: "unlisted")
}

/// Permission represents a permission level for access checks.
public struct Permission: RawRepresentable, Codable, Hashable, Sendable {
    public let rawValue: String
    public init(rawValue: String) { self.rawValue = rawValue }

    public static let permRead = Permission(rawValue: "read")
    public static let permWrite = Permission(rawValue: "write")
    /// PermUse is execute intent: run an app, load a skill/knowledge into an
    /// agent context, invoke an MCP tool. Distinct from read — a public
    /// resource is readable by everyone, but whether this caller may USE it is
    /// governed by their team/org usage policy (reach, INF-808).
    public static let permUse = Permission(rawValue: "use")
}

