/// LLMSettings is everything that configures a generation independent of the
/// conversation: context, sampling, system prompt, tools and output
/// constraints. Embedded (tstype extends) by BaseLLMInput — an agent's stored
/// configuration — and LLMInput — a single call — so a field added here
/// reaches both, and the call is built from the configuration by one
/// assignment.
/// 
/// Which model runs is not a setting: the app is the model. An app that
/// fronts several models (a router) declares its own `model` input.
public struct LLMSettings: Codable {
    public var contextSize: Int
    public var temperature: Double?
    public var topP: Double?
    public var topK: Int?
    public var minP: Double?
    public var frequencyPenalty: Double?
    public var presencePenalty: Double?
    public var repetitionPenalty: Double?
    public var seed: Int?
    public var stop: [String]?
    public var maxTokens: Int?
    public var reasoningEffort: String?
    public var reasoningMaxTokens: Int?
    public var systemPrompt: String
    public var tools: [Tool]?
    public var toolChoice: ToolChoice?
    public var responseFormat: ResponseFormat?

    public init(
        contextSize: Int = 0,
        temperature: Double? = nil,
        topP: Double? = nil,
        topK: Int? = nil,
        minP: Double? = nil,
        frequencyPenalty: Double? = nil,
        presencePenalty: Double? = nil,
        repetitionPenalty: Double? = nil,
        seed: Int? = nil,
        stop: [String]? = nil,
        maxTokens: Int? = nil,
        reasoningEffort: String? = nil,
        reasoningMaxTokens: Int? = nil,
        systemPrompt: String = "",
        tools: [Tool]? = nil,
        toolChoice: ToolChoice? = nil,
        responseFormat: ResponseFormat? = nil
    ) {
        self.contextSize = contextSize
        self.temperature = temperature
        self.topP = topP
        self.topK = topK
        self.minP = minP
        self.frequencyPenalty = frequencyPenalty
        self.presencePenalty = presencePenalty
        self.repetitionPenalty = repetitionPenalty
        self.seed = seed
        self.stop = stop
        self.maxTokens = maxTokens
        self.reasoningEffort = reasoningEffort
        self.reasoningMaxTokens = reasoningMaxTokens
        self.systemPrompt = systemPrompt
        self.tools = tools
        self.toolChoice = toolChoice
        self.responseFormat = responseFormat
    }

    enum CodingKeys: String, CodingKey {
        case contextSize = "context_size"
        case temperature = "temperature"
        case topP = "top_p"
        case topK = "top_k"
        case minP = "min_p"
        case frequencyPenalty = "frequency_penalty"
        case presencePenalty = "presence_penalty"
        case repetitionPenalty = "repetition_penalty"
        case seed = "seed"
        case stop = "stop"
        case maxTokens = "max_tokens"
        case reasoningEffort = "reasoning_effort"
        case reasoningMaxTokens = "reasoning_max_tokens"
        case systemPrompt = "system_prompt"
        case tools = "tools"
        case toolChoice = "tool_choice"
        case responseFormat = "response_format"
    }
}

