    public static let toolTypeFunction = ToolCallType(rawValue: "function")
}

/// ToolParamType represents a JSON Schema parameter type for tool definitions.
public struct ToolParamType: RawRepresentable, Codable, Hashable, Sendable {
    public let rawValue: String
    public init(rawValue: String) { self.rawValue = rawValue }

    public static let object = ToolParamType(rawValue: "object")
    public static let string = ToolParamType(rawValue: "string")
    public static let integer = ToolParamType(rawValue: "integer")
    public static let number = ToolParamType(rawValue: "number")
    public static let boolean = ToolParamType(rawValue: "boolean")
    public static let array = ToolParamType(rawValue: "array")
    public static let null = ToolParamType(rawValue: "null")
}

/// ToolCall represents a tool call from an LLM response (wire format)
/// This is a transport object for parsing LLM responses, not a database model
public struct ToolCall: Codable {
    public var id: String
    /// "function"
    public var type: ToolCallType
    public var function: ToolCallFunction

    public init(
        id: String = "",
        type: ToolCallType,
        function: ToolCallFunction
    ) {
        self.id = id
        self.type = type
        self.function = function
    }

    enum CodingKeys: String, CodingKey {
        case id = "id"
        case type = "type"
        case function = "function"
    }
}

/// ToolCallFunction contains the function name and arguments from an LLM tool call
public struct ToolCallFunction: Codable {
    public var name: String
    public var arguments: StringEncodedMap?

    public init(
        name: String = "",
        arguments: StringEncodedMap? = nil
    ) {
        self.name = name
        self.arguments = arguments
    }

    enum CodingKeys: String, CodingKey {
        case name = "name"
        case arguments = "arguments"
    }
}

/// LLMUsage contains token usage and performance metrics from an LLM response
public struct LLMUsage: Codable {
    public var stopReason: String
    public var timeToFirstToken: Double
    public var tokensPerSecond: Double
    public var promptTokens: Int
    public var completionTokens: Int
    public var totalTokens: Int
    public var reasoningTokens: Int
    public var reasoningTime: Double

    public init(
        stopReason: String = "",
        timeToFirstToken: Double = 0,
        tokensPerSecond: Double = 0,
        promptTokens: Int = 0,
        completionTokens: Int = 0,
        totalTokens: Int = 0,
        reasoningTokens: Int = 0,
        reasoningTime: Double = 0
    ) {
        self.stopReason = stopReason
        self.timeToFirstToken = timeToFirstToken
        self.tokensPerSecond = tokensPerSecond
        self.promptTokens = promptTokens
        self.completionTokens = completionTokens
        self.totalTokens = totalTokens
        self.reasoningTokens = reasoningTokens
        self.reasoningTime = reasoningTime
    }

    enum CodingKeys: String, CodingKey {
        case stopReason = "stop_reason"
        case timeToFirstToken = "time_to_first_token"
        case tokensPerSecond = "tokens_per_second"
        case promptTokens = "prompt_tokens"
        case completionTokens = "completion_tokens"
        case totalTokens = "total_tokens"
        case reasoningTokens = "reasoning_tokens"
        case reasoningTime = "reasoning_time"
    }
}

